result.text:
      gross = calc;
    } else if (Math.abs(calc - gross) > Math.max(1, gross * 0.02)) {
      out.notes.push(
        `No cuadra: ${fmtNum(kg, 2)} kg × ${fmtNum(price, 3)} €/kg son ${fmtEUR(calc)}, y el bruto del papel es ${fmtEUR(gross)}. Revísalo.`
      );
    }
  }

  if (net == null) {
    if (gross != null) net = round2(gross - dto);
  } else if (gross != null && dto) {
    const calc = round2(gross - dto);
    if (Math.abs(calc - net) > Math.max(1, Math.abs(net) * 0.02)) {
      out.notes.push(
        `No cuadra: bruto menos descuentos son ${fmtEUR(calc)}, y el líquido del papel dice ${fmtEUR(net)}. Revísalo.`
      );
    }
  }

  out.kg = kg != null && kg > 0 ? kg : null;
  out.price = price != null && price > 0 ? price : null;
  out.gross = gross;
  out.net = net;
  out.ok = out.kg != null && out.price != null;
  if (!out.ok) {
    out.notes.push(
      "No he sabido leer los kilos o el precio por kilo de esta liquidación. Escríbelos a mano antes de guardar."
    );
  }
  return out;
}
